inline constexpr GameProfile kBuiltin{kId, kSerialized};
inline const GameProfile* FindProfile(const std::string& id) { return id == kId ? &kBuiltin : nullptr; }
inline size_t ChecksumLength(uint16_t id) {
    if (id == 0) return 3876;
    if (id == 4) return 3480;
    if (id == 13) return 1104;
    return kContainerChecksumDefaultLength;
}
inline bool Opaque(uint16_t id) { for (auto value : kContainerChecksumOpaqueIds) if (id == value) return true; return false; }
inline std::string CatalogAsset(const char* filename) {
    if (std::strcmp(filename, "pokemon.txt") == 0) return "data/pokemon.txt";
    if (std::strcmp(filename, "items.txt") == 0) return "data/items.txt";
    if (std::strcmp(filename, "moves.txt") == 0) return "data/moves.txt";
    if (std::strcmp(filename, "abilities.txt") == 0) return "data/abilities.txt";
    if (std::strcmp(filename, "move_table_from_rom.json") == 0) return "data/move_table_from_rom.json";
    if (std::strcmp(filename, "species_base_stats.json") == 0) return "data/species_base_stats.json";
    if (std::strcmp(filename, "species_identity_meta.json") == 0) return "data/species_identity_meta.json";
    if (std::strcmp(filename, "species_growth_rates.json") == 0) return "data/species_growth_rates.json";
    if (std::strcmp(filename, "species_abilities_meta.json") == 0) return "data/species_abilities_meta.json";
    if (std::strcmp(filename, "item_pocket_map.json") == 0) return "data/item_pocket_map.json";
    return {};
}
struct NativeIdentity { std::string profile_id; uint32_t native_id; };
inline NativeIdentity Identity(uint32_t id) { return {kId, id}; }
enum class RecordState { Empty, Known, Unknown };
inline RecordState InspectPcRecord(const uint8_t* raw, size_t size, bool known_species) {
    if (size != kCodecsPcRecordSize) return RecordState::Unknown;
    const auto off = kCodecsPcFieldsSpecies;
    const auto id = uint16_t(raw[off]) | (uint16_t(raw[off+1]) << 8);
    return id == 0 ? RecordState::Empty : known_species ? RecordState::Known : RecordState::Unknown;
}
